def _et(bars):
    """Minute-of-day, session index, weekday and calendar day, in New York."""
    import datetime
    mins = []
    sess = []
    dow = []
    dom = []
    last = None
    s = -1
    for b in bars:
        ts = str(b["t"])
        y = int(ts[0:4]); mo = int(ts[5:7]); d = int(ts[8:10])
        hh = int(ts[11:13]); mi = int(ts[14:16])
        if mo < 3 or mo > 11:
            dst = False
        elif 3 < mo < 11:
            dst = True
        elif mo == 3:
            w = datetime.date(y, 3, 1).weekday()
            dst = d >= 1 + ((6 - w) % 7) + 7
        else:
            w = datetime.date(y, 11, 1).weekday()
            dst = d < 1 + ((6 - w) % 7)
        t = (datetime.datetime(y, mo, d, hh, mi)
             - datetime.timedelta(minutes=240 if dst else 300))
        key = (t.year, t.month, t.day)
        if key != last:
            last = key
            s += 1
        mins.append(t.hour * 60 + t.minute)
        sess.append(s)
        dow.append(t.weekday())
        dom.append(t.day)
    return mins, sess, dow, dom


def family_init(ctx):
    import statistics
    bars = ctx.bars
    n = len(bars)
    hi = [float(b["h"]) for b in bars]
    lo = [float(b["l"]) for b in bars]
    cl = [float(b["c"]) for b in bars]
    vo = [float(b.get("v") or 0.0) for b in bars]
    mins, sess, dow, dom = _et(bars)

    band = float(ctx.p.pin_band)
    reach = float(ctx.p.reach_atr)
    prox = float(ctx.p.rel_prox)
    abort = float(ctx.p.abort_atr)
    entry_m = int(ctx.p.entry_min)
    flat_m = int(ctx.p.flat_min)
    monthly = int(ctx.p.monthly_only)
    drift_n = int(ctx.p.drift_n)
    dvmin = float(ctx.p.dv_min)
    pxmin = float(ctx.p.px_min)

    # ---------- per-session summary ----------
    order = []
    sh = {}
    sl = {}
    sc = {}
    sdv = {}
    sday = {}
    swd = {}
    sdom = {}
    first_rth = {}
    for j in range(n):
        if mins[j] < 570 or mins[j] >= 960:
            continue
        s = sess[j]
        if s not in sh:
            sh[s] = hi[j]
            sl[s] = lo[j]
            sdv[s] = 0.0
            order.append(s)
            first_rth[s] = j
            swd[s] = dow[j]
            sdom[s] = dom[j]
        sh[s] = max(sh[s], hi[j])
        sl[s] = min(sl[s], lo[j])
        sc[s] = cl[j]
        sdv[s] += cl[j] * vo[j]

    pos = dict((s, k) for k, s in enumerate(order))
    trs = []
    atrd = {}
    dvmed = {}
    prev = None
    for s in order:
        if len(trs) >= int(ctx.p.min_days):
            w = trs[-int(ctx.p.atr_days):]
            atrd[s] = sum(w) / len(w)
            dv = [sdv[q] for q in order[max(0, pos[s] - 20):pos[s]]]
            if dv:
                dvmed[s] = statistics.median(dv)
        tr = (sh[s] - sl[s]) if prev is None else max(
            sh[s] - sl[s], abs(sh[s] - prev), abs(sl[s] - prev))
        prev = sc[s]
        trs.append(tr)

    # ---------- which sessions are expirations ----------
    exp = set()
    for s in order:
        if swd[s] != 4:
            continue
        if monthly and not (15 <= sdom[s] <= 21):
            continue
        exp.add(s)

    def strike(px):
        inc = 1.0 if px < 25.0 else (2.5 if px < 200.0 else 5.0)
        return round(px / inc) * inc, inc

    sig = [0] * n
    meta = [None] * n

    for s in exp:
        k = pos[s]
        # ---------- the pin leg: the Wednesday and Thursday before ----------
        for back in range(1, 4):
            if k - back < 0:
                break
            q = order[k - back]
            if swd[q] not in (2, 3):
                continue
            a = atrd.get(q)
            if not a or a <= 0:
                continue
            if dvmed.get(q, 0.0) < dvmin:
                continue
            j = None
            for x in range(first_rth[q], n):
                if sess[x] != q:
                    break
                if mins[x] >= entry_m:
                    j = x
                    break
            if j is None:
                continue
            p = cl[j]
            if p < pxmin:
                continue
            kk, inc = strike(p)
            dist = p - kk
            if abs(dist) < band * (inc / 2.0):
                continue
            if abs(dist) > reach * a:
                continue
            sig[j] = -1 if dist > 0 else 1
            meta[j] = (s, kk, a, abs(dist))

        # ---------- the release leg: the session after expiration ----------
        if k + 1 < len(order):
            r = order[k + 1]
            p = sc[s]
            kk, inc = strike(p)
            if abs(p - kk) <= prox * p:
                wed = None
                for back in range(1, 4):
                    if k - back < 0:
                        break
                    if swd[order[k - back]] == 2:
                        wed = k - back
                        break
                if wed is not None and wed - drift_n >= 0:
                    c1 = sc[order[wed]]
                    c0 = sc[order[wed - drift_n]]
                    if c0 > 0 and c1 != c0:
                        j = first_rth[r]
                        if sig[j] == 0:
                            sig[j] = 1 if c1 > c0 else -1
                            meta[j] = (r, None, atrd.get(r), None)

    eod = [1 if mins[j] >= flat_m or mins[j] < 570 or mins[j] >= 960 else 0
           for j in range(n)]

    ctx.sig = ctx.series(sig, "pin")
    ctx.meta = ctx.series(meta, "pin_meta")
    ctx.sessx = ctx.series(sess, "session")
    ctx.eod = ctx.series(eod, "eod")
    ctx._m = None


def signal(ctx, i):
    s = ctx.sig[i]
    if s and not ctx.positions:
        ctx._m = ctx.meta[i]
    return int(s)


def exit_signal(ctx, i):
    """Never carried into a second session past its own deadline: the pin leg
    is closed on the expiration session, the release leg on its own session.
    A pin that runs away from the strike is abandoned early."""
    if ctx._m is None:
        return False
    last_sess, kk, a, d0 = ctx._m
    s = ctx.sessx[i]
    if s > last_sess:
        return True
    if s == last_sess and ctx.eod[i]:
        return True
    if kk is not None and a and d0 is not None:
        if abs(ctx.c[i] - kk) > d0 + float(ctx.p.abort_atr) * a:
            return True
    return False
